import json, os, sys, io, time, glob
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')

from google import genai

api_key = None
for p in ['D:/code/invesments/master_investments_mmo/.claude/.env', 'D:/code/invesments/master_investments/.claude/.env']:
    if os.path.exists(p):
        with open(p) as f:
            for line in f:
                if 'GEMINI_API_KEY=' in line or 'GOOGLE_API_KEY=' in line:
                    api_key = line.split('=', 1)[1].strip().strip('"').strip("'")
                    break
    if api_key: break

client = genai.Client(api_key=api_key)

audio_files = sorted(glob.glob('audio/*.mp3'))
results = {}

for af in audio_files:
    vid_id = os.path.basename(af).replace('.mp3', '')
    fsize = os.path.getsize(af)
    print(f'Transcribing {vid_id} ({fsize//1024}KB)...')

    with open(af, 'rb') as f:
        audio_data = f.read()

    try:
        response = client.models.generate_content(
            model='gemini-2.0-flash',
            contents=[
                {
                    'inline_data': {
                        'mime_type': 'audio/mpeg',
                        'data': __import__('base64').b64encode(audio_data).decode()
                    }
                },
                "Transcribe toàn bộ audio tiếng Việt này. Output NGUYÊN VĂN lời nói, không tóm tắt, không bỏ sót. Nếu có nhạc nền hoặc tiếng ồn, bỏ qua, chỉ ghi lời nói."
            ]
        )
        results[vid_id] = response.text
        print(f'  OK: {len(response.text)} chars')
    except Exception as e:
        results[vid_id] = f'ERROR: {str(e)[:200]}'
        print(f'  FAIL: {str(e)[:80]}')

    time.sleep(3)

with open('transcripts.json', 'w', encoding='utf-8') as f:
    json.dump(results, f, ensure_ascii=False, indent=2)

print(f'\nDone: {len(results)} videos transcribed')
